"""Conversion of the non-SSA control-flow IR into pruned SSA form.

The entry point :func:`to_ssa` takes a :class:`Module` produced by
:func:`lower_module` and returns a brand new, traversable and renderable
SSA :class:`Module`; the input module is never mutated.  Feeding an SSA
module back in yields a structurally and textually equivalent copy (no new
phi nodes, no renumbering), and any non-:class:`Module` object raises
:class:`TypeError`.

Algorithm (Cytron et al., with pruning)
--------------------------------------
1. Compute reachable blocks, predecessors and the dominator tree from the
   CFG induced by the terminators.
2. Every value definition site (a parameter slot, a slot copy, or a
   possibly multi-written temporary such as a short-circuit result) gets a
   phi at iterated dominance frontier blocks.
3. A dominator-tree walk renames every definition to a fresh SSA value,
   fills phi entries from the stacks live on each outgoing edge, and only
   ever visits reachable edges, so unreachable predecessors never appear in
   a phi.
4. Dead (result-unused) and trivial (one distinct incoming value) phis are
   removed to a fixpoint; chains collapse in turn.
5. Values are numbered deterministically per function -- parameters in
   order, then blocks in id order, phis before ordinary instructions -- so
   repeated conversion of the same module is byte-identical and independent
   of set or dict iteration order and object identity.
"""
from .ir_nodes import (
    BinOp,
    Block,
    Branch,
    Call,
    Const,
    Copy,
    Function,
    Jump,
    Module,
    Parameter,
    Phi,
    Return,
    Slot,
    Temp,
)


def to_ssa(module: Module) -> Module:
    """Return an SSA copy of ``module``.

    The input module is left untouched.  A module already in SSA form is
    copied to an equivalent SSA module (same phi nodes, same numbering).

    :raises TypeError: if ``module`` is not a :class:`Module` instance.
    """
    if not isinstance(module, Module):
        raise TypeError(
            f"to_ssa expects a Module, got {type(module).__name__}"
        )
    if getattr(module, "ssa", False):
        return _clone_ssa_module(module)
    return Module(
        [_convert_function(func) for func in module.functions], ssa=True
    )


# --------------------------------------------------------------------------
# CFG analysis
# --------------------------------------------------------------------------


def _terminator_edges(block: Block):
    """Return the reachable successor blocks of a block in fixed order."""
    term = block.terminator
    if isinstance(term, Jump):
        return [term.target]
    if isinstance(term, Branch):
        return [term.true_target, term.false_target]
    return []


class _CFG:
    def __init__(self, func: Function):
        self.blocks = list(func.blocks)
        self.index = {block: i for i, block in enumerate(self.blocks)}
        self.succs: dict[Block, list[Block]] = {
            block: _terminator_edges(block) for block in self.blocks
        }
        self.reachable = self._reachable_set(func.entry)
        self.preds: dict[Block, list[Block]] = {
            block: [] for block in self.blocks
        }
        for block in self.blocks:
            if block not in self.reachable:
                continue
            for target in self.succs[block]:
                if target in self.reachable:
                    self.preds[target].append(block)

    def _reachable_set(self, entry: Block) -> set[Block]:
        seen = {entry}
        stack = [entry]
        while stack:
            block = stack.pop()
            for target in self.succs[block]:
                if target not in seen:
                    seen.add(target)
                    stack.append(target)
        return seen

    def ordered(self, blocks) -> list[Block]:
        """Sort an iterable of blocks by deterministic block index."""
        return sorted(blocks, key=lambda b: self.index[b])


def _reverse_postorder(cfg: _CFG, entry: Block) -> list[Block]:
    order: list[Block] = []
    visited = {entry}
    stack = [(entry, 0)]
    while stack:
        block, pos = stack[-1]
        successors = cfg.succs[block]
        if pos < len(successors):
            stack[-1] = (block, pos + 1)
            target = successors[pos]
            if target in cfg.reachable and target not in visited:
                visited.add(target)
                stack.append((target, 0))
        else:
            order.append(block)
            stack.pop()
    order.reverse()
    return order


def _dominators(cfg: _CFG, entry: Block):
    """Return (idom, rpo_index) over reachable blocks.

    Cooper, Harvey and Waters' iterative fixed point; predecessors are
    visited in block-index order, though the least fixed point is
    order-independent.
    """
    rpo = _reverse_postorder(cfg, entry)
    rpo_index = {block: i for i, block in enumerate(rpo)}
    preds_order = {
        block: cfg.ordered(
            p for p in cfg.preds[block] if p in rpo_index
        )
        for block in rpo
    }

    def intersect(a: Block, b: Block) -> Block:
        finger1, finger2 = a, b
        while finger1 is not finger2:
            while rpo_index[finger1] > rpo_index[finger2]:
                finger1 = idom[finger1]
            while rpo_index[finger2] > rpo_index[finger1]:
                finger2 = idom[finger2]
        return finger1

    idom: dict[Block, Block] = {entry: entry}
    changed = True
    while changed:
        changed = False
        for block in rpo[1:]:
            new_idom = next(p for p in preds_order[block] if p in idom)
            for pred in preds_order[block]:
                if pred is new_idom or pred not in idom:
                    continue
                new_idom = intersect(pred, new_idom)
            if idom.get(block) is not new_idom:
                idom[block] = new_idom
                changed = True
    return idom, rpo_index


def _dominance_frontiers(cfg: _CFG, idom) -> dict[Block, list[Block]]:
    frontiers: dict[Block, set[Block]] = {
        block: set() for block in cfg.reachable
    }
    for block in cfg.ordered(cfg.reachable):
        if len(cfg.preds[block]) < 2:
            continue
        for pred in cfg.preds[block]:
            runner = pred
            while runner is not idom[block]:
                frontiers[runner].add(block)
                runner = idom[runner]
    return {block: cfg.ordered(blocks) for block, blocks in frontiers.items()}


# --------------------------------------------------------------------------
# Per-function conversion
# --------------------------------------------------------------------------


class _Converter:
    def __init__(self, func: Function):
        self.func = func
        self.cfg = _CFG(func)
        # Original value references (Temp/Slot) tracked during conversion.
        self._fresh_counter = 0
        self.placeholder_type: dict[Temp, str] = {}

    def fresh(self, typ: str) -> Temp:
        temp = Temp(self._fresh_counter, typ)
        self._fresh_counter += 1
        return temp

    def convert(self) -> Function:
        cfg = self.cfg
        entry = self.func.entry
        idom, _ = _dominators(cfg, entry)
        frontiers = _dominance_frontiers(cfg, idom)

        # New blocks keep the original ids and order, hence labels.
        new_blocks = [Block(block.id) for block in cfg.blocks]
        block_map = {
            old: new for old, new in zip(cfg.blocks, new_blocks)
        }

        # -- gather definition sites and slot parameter defs -------------
        param_defs: dict[Slot, Temp] = {}
        defs: dict[object, list[Block]] = {}

        def add_def(ref, block: Block) -> None:
            defs.setdefault(ref, []).append(block)

        for param in self.func.params:
            temp = self.fresh(param.slot.type)
            param_defs[param.slot] = temp
            add_def(param.slot, entry)

        for block in cfg.blocks:
            for ins in block.instructions:
                add_def(ins.dest, block)

        # -- insert phi placeholders at iterated dominance frontiers -----
        phi_origin: dict[Phi, object] = {}
        block_phis: dict[Block, list[Phi]] = {}
        already: dict[Block, set[object]] = {
            block: set() for block in cfg.reachable
        }
        for ref, sites in defs.items():
            typ = ref.type
            worklist = list(sites)
            while worklist:
                site = worklist.pop()
                for frontier in frontiers.get(site, ()):  # reachable only
                    if ref in already[frontier]:
                        continue
                    already[frontier].add(ref)
                    phi = Phi(self.fresh(typ), {})
                    phi_origin[phi] = ref
                    block_phis.setdefault(frontier, []).append(phi)
                    if not any(s is frontier for s in worklist):
                        worklist.append(frontier)

        # Phis within a block are ordered by the deterministic order in
        # which the definition worklists reached the block: refs are
        # iterated in a fixed order below.
        ref_order = self._ref_order(defs)
        for block in cfg.ordered(block_phis):
            block_phis[block].sort(
                key=lambda phi: ref_order[phi_origin[phi]]
            )

        # -- rename over the dominator tree ------------------------------
        stacks: dict[object, list[Temp]] = {}
        for slot, temp in param_defs.items():
            stacks[slot] = [temp]

        new_params = [
            Parameter(param.name, param.slot, param_defs[param.slot])
            for param in self.func.params
        ]

        def top(ref) -> Temp | None:
            stack = stacks.get(ref)
            return stack[-1] if stack else None

        # Clone reachable blocks via an idom-tree DFS so stacks encode
        # exactly the definitions dominating each block.
        children: dict[Block, list[Block]] = {
            block: [] for block in cfg.reachable
        }
        for block in cfg.ordered(cfg.reachable):
            if block is not entry:
                children[idom[block]].append(block)
        for child_list in children.values():
            child_list.sort(key=lambda b: cfg.index[b])

        loose_map: dict[object, Temp] = {}

        def map_use(ref):
            if isinstance(ref, Temp):
                mapped = top(ref)
                if mapped is not None:
                    return mapped
                # A temporary read before any dominating definition only
                # occurs in unreachable code; invent a stable placeholder.
                return loose_map.setdefault(ref, self.fresh(ref.type))
            mapped = top(ref)
            if mapped is None:
                # A slot read on a path where the name is not defined.
                # Semantic analysis rules this out for reachable uses; the
                # placeholder is consumed only by a phi that prunes away.
                mapped = loose_map.get(ref)
                if mapped is None:
                    mapped = self.fresh(ref.type)
                    loose_map[ref] = mapped
            return mapped

        def map_block(old: Block, new: Block) -> None:
            saved = {ref: len(stack) for ref, stack in stacks.items()}

            for phi in block_phis.get(old, ()):
                ref = phi_origin[phi]
                stacks.setdefault(ref, []).append(phi.dest)

            for ins in old.instructions:
                new.instructions.append(self._clone_ins(ins, map_use))
                # The cloned definition binds the original reference name.
                dest = self._cloned_dest(new.instructions[-1])
                stacks.setdefault(ins.dest, []).append(dest)

            new.terminator = self._clone_terminator(
                old.terminator, block_map, map_use
            )

            for successor in cfg.succs[old]:
                if successor not in cfg.reachable:
                    continue
                for phi in block_phis.get(successor, ()):
                    value = top(phi_origin[phi])
                    if value is None:
                        value = map_use(phi_origin[phi])
                    phi.entries[new] = value

            for child in children[old]:
                map_block(child, block_map[child])

            for ref, length in saved.items():
                del stacks[ref][length:]

        map_block(entry, block_map[entry])

        for old, new in block_map.items():
            phis = block_phis.get(old, ())
            new.phis = list(phis)
            if old not in cfg.reachable:
                self._clone_unreachable(old, new, block_map)

        self._prune(new_blocks)
        canonical = self._canonical_numbering(new_params, new_blocks)
        params_by_id, temp_map = canonical
        self._apply_numbering(
            new_params, new_blocks, block_map, params_by_id, temp_map
        )

        return Function(
            self.func.name,
            new_params,
            self.func.ret_type,
            [],
            new_blocks,
            block_map[entry],
            ssa=True,
        )

    def _ref_order(self, defs: dict[object, list[Block]]) -> dict[object, int]:
        """Deterministic ordering key for the defined original refs."""
        ordered_params = [p.slot for p in self.func.params]
        others = [
            ref for ref in defs
            if not any(ref is slot for slot in ordered_params)
        ]

        def key(ref):
            sites = defs[ref]
            first = min(self.cfg.index[b] for b in sites)
            if isinstance(ref, Slot):
                return (0, ref.id, first)
            return (1, ref.id, first)

        others.sort(key=key)
        return {ref: i for i, ref in enumerate([*ordered_params, *others])}

    # -- instruction cloning ----------------------------------------------

    def _cloned_dest(self, ins) -> Temp:
        return ins.dest

    def _clone_ins(self, ins, map_use):
        if isinstance(ins, Const):
            return Const(self.fresh(ins.dest.type), ins.value)
        if isinstance(ins, Copy):
            return Copy(self.fresh(ins.dest.type), map_use(ins.src))
        if isinstance(ins, BinOp):
            return BinOp(
                self.fresh(ins.dest.type),
                ins.operator,
                map_use(ins.left),
                map_use(ins.right),
                ins.kind,
                ins.type,
            )
        # Call
        return Call(
            self.fresh(ins.dest.type),
            ins.name,
            [map_use(arg) for arg in ins.args],
            ins.type,
        )

    def _clone_terminator(self, term, block_map, map_use):
        if isinstance(term, Return):
            return Return(None if term.value is None else map_use(term.value))
        if isinstance(term, Jump):
            return Jump(block_map[term.target])
        if isinstance(term, Branch):
            return Branch(
                map_use(term.cond),
                block_map[term.true_target],
                block_map[term.false_target],
            )
        return None  # pragma: no cover - lowerer always terminates blocks

    def _clone_unreachable(self, old: Block, new: Block, block_map) -> None:
        """Structurally clone a block unreachable from the entry.

        Such blocks never occur in IR produced by ``lower_module`` (every
        created block is targeted by a reachable terminator), but cloning
        them keeps labels, order and terminators stable for hand-fed input
        while still giving every write a unique SSA definition.
        """
        loose: dict[object, Temp] = {}

        def loose_use(ref):
            mapped = loose.get(ref)
            if mapped is None:
                mapped = self.fresh(ref.type)
                loose[ref] = mapped
            return mapped

        new.instructions = []
        for ins in old.instructions:
            cloned = self._clone_ins(ins, loose_use)
            loose[ins.dest] = cloned.dest
            new.instructions.append(cloned)
        term = old.terminator
        if isinstance(term, Return):
            new.terminator = Return(
                None if term.value is None else loose_use(term.value)
            )
        elif isinstance(term, Jump):
            new.terminator = Jump(block_map[term.target])
        elif isinstance(term, Branch):
            new.terminator = Branch(
                loose_use(term.cond),
                block_map[term.true_target],
                block_map[term.false_target],
            )

    # -- phi pruning -------------------------------------------------------

    def _prune(self, blocks: list[Block]) -> None:
        """Remove dead and trivial phi nodes to a fixpoint."""
        while True:
            users = self._phi_users(blocks)

            dead = None
            trivial = None
            for block in blocks:
                for phi in list(block.phis):
                    incoming = set(phi.entries.values())
                    incoming.discard(None)
                    if not users.get(id(phi.dest)):
                        dead = (block, phi)
                        break
                    if len(incoming) == 1:
                        trivial = (block, phi, next(iter(incoming)))
                        break
                if dead or trivial:
                    break

            if dead is not None:
                block, phi = dead
                block.phis.remove(phi)
                continue
            if trivial is not None:
                block, phi, value = trivial
                block.phis.remove(phi)
                self._replace_value(blocks, phi.dest, value)
                continue
            break

    def _phi_users(self, blocks: list[Block]) -> dict[int, list[Phi]]:
        """Map a phi result id to the other phi nodes that read it."""
        users: dict[int, list[Phi]] = {}

        def note(value) -> None:
            if isinstance(value, Temp):
                users.setdefault(id(value), [])

        for block in blocks:
            for phi in block.phis:
                for value in phi.entries.values():
                    note(value)
            for ins in block.instructions:
                if isinstance(ins, Copy):
                    note(ins.src)
                elif isinstance(ins, BinOp):
                    note(ins.left)
                    note(ins.right)
                elif isinstance(ins, Call):
                    for arg in ins.args:
                        note(arg)
            term = block.terminator
            if isinstance(term, Return) and term.value is not None:
                note(term.value)
            elif isinstance(term, Branch):
                note(term.cond)
        return users

    def _replace_value(
        self, blocks: list[Block], old: Temp, new: Temp
    ) -> None:
        def subst(value):
            return new if value is old else value

        for block in blocks:
            for phi in block.phis:
                phi.entries = {
                    pred: subst(value) for pred, value in phi.entries.items()
                }
            for ins in block.instructions:
                if isinstance(ins, Copy):
                    ins.src = subst(ins.src)
                elif isinstance(ins, BinOp):
                    ins.left = subst(ins.left)
                    ins.right = subst(ins.right)
                elif isinstance(ins, Call):
                    ins.args = [subst(arg) for arg in ins.args]
            term = block.terminator
            if isinstance(term, Return) and term.value is not None:
                term.value = subst(term.value)
            elif isinstance(term, Branch):
                term.cond = subst(term.cond)

    # -- canonical numbering ----------------------------------------------

    def _canonical_numbering(self, params: list[Parameter], blocks):
        """Assign deterministic per-function ids: params, then block phis
        and ordinary instructions in block id order."""
        temp_map: dict[Temp, Temp] = {}
        params_by_id: dict[int, Temp] = {}
        next_id = 0

        def assign(temp: Temp) -> Temp:
            nonlocal next_id
            mapped = temp_map.get(temp)
            if mapped is None:
                mapped = Temp(next_id, temp.type)
                next_id += 1
                temp_map[temp] = mapped
            return mapped

        for param in params:
            params_by_id[id(param.temp)] = assign(param.temp)

        for block in blocks:
            for phi in block.phis:
                assign(phi.dest)
                for value in phi.entries.values():
                    if value is not None:
                        assign(value)
            for ins in block.instructions:
                assign(ins.dest)
                self._assign_operands(ins, assign)
            term = block.terminator
            if isinstance(term, Return) and term.value is not None:
                assign(term.value)
            elif isinstance(term, Branch):
                assign(term.cond)
        return params_by_id, temp_map

    def _assign_operands(self, ins, assign) -> None:
        if isinstance(ins, Copy):
            assign(ins.src)
        elif isinstance(ins, BinOp):
            assign(ins.left)
            assign(ins.right)
        elif isinstance(ins, Call):
            for arg in ins.args:
                assign(arg)

    def _apply_numbering(
        self, params, blocks, block_map, params_by_id, temp_map
    ) -> None:
        def numbered(value):
            if value is None:
                return None
            mapped = temp_map.get(value)
            if mapped is None:
                # Operand-only value (e.g. inside unreachable code) that was
                # not walked above: allocate on the fly in encounter order.
                mapped = Temp(len(temp_map), value.type)
                temp_map[value] = mapped
            return mapped

        for param in params:
            param.temp = params_by_id[id(param.temp)]

        for block in blocks:
            ordered_phis = sorted(
                block.phis, key=lambda phi: self.cfg.index
            ) if False else block.phis
            new_phis = []
            for phi in block.phis:
                entries = {
                    block_map.get(pred, pred): numbered(value)
                    for pred, value in sorted(
                        phi.entries.items(),
                        key=lambda item: self._pred_key(item[0], block_map),
                    )
                }
                new_phis.append(Phi(numbered(phi.dest), entries))
            block.phis = new_phis

            for ins in block.instructions:
                ins.dest = numbered(ins.dest)
                if isinstance(ins, Copy):
                    ins.src = numbered(ins.src)
                elif isinstance(ins, BinOp):
                    ins.left = numbered(ins.left)
                    ins.right = numbered(ins.right)
                elif isinstance(ins, Call):
                    ins.args = [numbered(arg) for arg in ins.args]
            term = block.terminator
            if isinstance(term, Return) and term.value is not None:
                term.value = numbered(term.value)
            elif isinstance(term, Branch):
                term.cond = numbered(term.cond)

    def _pred_key(self, pred, block_map):
        block = block_map.get(pred, pred)
        return self.cfg.index.get(pred, block.id)


def _convert_function(func: Function) -> Function:
    return _Converter(func).convert()


# --------------------------------------------------------------------------
# Idempotent cloning of an already-SSA module
# --------------------------------------------------------------------------


def _clone_ssa_module(module: Module) -> Module:
    return Module(
        [_clone_ssa_function(func) for func in module.functions], ssa=True
    )


def _clone_ssa_function(func: Function) -> Function:
    new_blocks = [Block(block.id) for block in func.blocks]
    block_map = dict(zip(func.blocks, new_blocks))
    temp_map: dict[Temp, Temp] = {}
    next_id = 0

    def canonical(temp: Temp) -> Temp:
        nonlocal next_id
        mapped = temp_map.get(temp)
        if mapped is None:
            mapped = Temp(next_id, temp.type)
            next_id += 1
            temp_map[temp] = mapped
        return mapped

    # Definition order fixes the ids: parameters, then phis and ordinary
    # instructions in block order -- identical to the module's own numbering.
    new_params: list[Parameter] = []
    for param in func.params:
        temp = canonical(param.temp)
        new_params.append(Parameter(param.name, param.slot, temp))

    for block, new_block in zip(func.blocks, new_blocks):
        for phi in block.phis:
            canonical(phi.dest)
        for ins in block.instructions:
            canonical(ins.dest)

    def ref(value):
        return temp_map[value] if value is not None else None

    for block, new_block in zip(func.blocks, new_blocks):
        for phi in block.phis:
            entries = {
                block_map[pred]: ref(value)
                for pred, value in sorted(
                    phi.entries.items(),
                    key=lambda item: item[0].id,
                )
            }
            new_block.phis.append(Phi(ref(phi.dest), entries))
        for ins in block.instructions:
            if isinstance(ins, Const):
                clone = Const(ref(ins.dest), ins.value)
            elif isinstance(ins, Copy):
                clone = Copy(ref(ins.dest), ref(ins.src))
            elif isinstance(ins, BinOp):
                clone = BinOp(
                    ref(ins.dest), ins.operator, ref(ins.left),
                    ref(ins.right), ins.kind, ins.type,
                )
            else:
                clone = Call(
                    ref(ins.dest), ins.name,
                    [ref(arg) for arg in ins.args], ins.type,
                )
            new_block.instructions.append(clone)
        term = block.terminator
        if isinstance(term, Return):
            new_block.terminator = Return(ref(term.value))
        elif isinstance(term, Jump):
            new_block.terminator = Jump(block_map[term.target])
        elif isinstance(term, Branch):
            new_block.terminator = Branch(
                ref(term.cond),
                block_map[term.true_target],
                block_map[term.false_target],
            )

    return Function(
        func.name,
        new_params,
        func.ret_type,
        list(func.locals),
        new_blocks,
        block_map[func.entry],
        ssa=True,
    )

