    """Ids of phi results live outside the phi-only reference graph."""
    live: set[int] = set()
    for block in blocks:
        for ins in block.instructions:
            for value in _operands(ins):
                live.add(id(value))
        for value in _term_operands(block.terminator):
            live.add(id(value))

    # A phi is live when read by an already-live phi; iterate to a
    # fixpoint so chains terminate at a real user and cycles do not.
    changed = True
    while changed:
        changed = False
        for block in blocks:
            for phi in block.phis:
                if id(phi.dest) in live:
