from compiler_ir import lower_module, to_ssa
from compiler_ir.ir_nodes import Const, Copy, BinOp, Call, Return, Jump, Branch, Slot, Phi, Temp, Block

def edges(b):
    t = b.terminator
    if isinstance(t, Jump): return [t.target]
    if isinstance(t, Branch): return [t.true_target, t.false_target]
    return []

def verify(fn):
    blocks = fn.blocks
    # 1. numbering: unique dense ids from 0
    ids = []
    for p in fn.params:
        assert isinstance(p.temp, Temp), "param must have temp"
        ids.append(p.temp.id)
    for b in blocks:
        for ph in b.phis: ids.append(ph.dest.id)
        for ins in b.instructions: ids.append(ins.dest.id)
    assert sorted(ids) == list(range(len(ids))), f"non-dense ids {sorted(ids)} in {fn.name}"

    # 2. no Slot anywhere
    def no_slot(v, ctx):
        assert not isinstance(v, Slot), f"slot leaked {v} in {fn.name} {ctx}"
    for b in blocks:
        for ph in b.phis:
            for v in ph.entries.values(): no_slot(v, "phi")
        for ins in b.instructions:
            if isinstance(ins, Copy): no_slot(ins.src,"copy")
            elif isinstance(ins, BinOp): no_slot(ins.left,"bin"); no_slot(ins.right,"bin")
            elif isinstance(ins, Call):
                for a in ins.args: no_slot(a,"call")
        t=b.terminator
        if isinstance(t, Return) and t.value is not None: no_slot(t.value,"ret")
        if isinstance(t, Branch): no_slot(t.cond,"br")

    # 3. reaching defs via dominators: compute idom
    entry = fn.entry
    succs = {b: edges(b) for b in blocks}
    # reachability
    reach={entry}; st=[entry]
    while st:
        x=st.pop()
        for y in succs[x]:
            if y not in reach: reach.add(y); st.append(y)
    preds={b:[] for b in blocks}
    for x in blocks:
        if x in reach:
            for y in succs[x]:
                if y in reach: preds[y].append(x)
    # simple dominator sets fixed point
    dom={entry:{entry}}
    rpo=[]
    seen={entry}; stack=[(entry,0)]
    while stack:
        x,i=stack[-1]
        if i<len(succs[x]):
            stack[-1]=(x,i+1); y=succs[x][i]
            if y in reach and y not in seen: seen.add(y); stack.append((y,0))
        else:
            rpo.append(x); stack.pop()
    rpo=rpo[::-1]
    for b in rpo[1:]:
        ps=[p for p in preds[b] if p in dom]
        dom[b]=set.intersection(*[dom[p] for p in ps]) | {b} if ps else {b}
    # def block map
    defblock={}
    for p in fn.params: defblock[id(p.temp)]=entry
    for b in blocks:
        for ph in b.phis: defblock[id(ph.dest)]=b
        for ins in b.instructions: defblock[id(ins.dest)]=b

    def dominates(db, ub):
        # phi def is available at end? phi defs considered at top of block
        return ub in dom[db]

    # 4. each non-phi use must be dominated by its def
    def check_use(v, ub, top=False):
        db=defblock.get(id(v))
        assert db is not None, f"use of undefined {v} in {fn.name} block {ub.label}"
        if db is ub and not top:
            # must be a non-phi instruction def used after def within same block:
            # find positions
            pass
        else:
            assert dominates(db,ub), f"def {v}@{db.label} does not dominate use@{ub.label} in {fn.name}"

    for b in blocks:
        if b not in reach: continue
        # phi entries exactly match reachable preds, sorted by label
        for ph in b.phis:
            keys=list(ph.entries.keys())
            assert [k.id for k in keys]==sorted(k.id for k in keys), "phi entries not sorted"
            assert set(keys)==set(preds[b]), f"phi preds mismatch in {fn.name} {b.label}: {[k.label for k in keys]} vs {[p.label for p in preds[b]]}"
            for pred,v in ph.entries.items():
                db=defblock.get(id(v))
                assert db is not None, f"phi incoming undefined {v}"
                # edge-specific: def dominates pred (or phi in pred block ok)
                assert dominates(db,pred) or db is pred, f"phi incoming {v} not available on edge {pred.label}->{b.label}"
        # ordinary uses
        local_defs=set()
        for ph in b.phis: local_defs.add(id(ph.dest))
        for ins in b.instructions:
            for v in (getattr(ins,'src',None) and [ins.src] or []): check_use(v,b)
            if isinstance(ins,BinOp): check_use(ins.left,b); check_use(ins.right,b)
            if isinstance(ins,Call):
                for a in ins.args: check_use(a,b)
            local_defs.add(id(ins.dest))
        t=b.terminator
        if isinstance(t,Return) and t.value is not None: check_use(t.value,b)
        if isinstance(t,Branch): check_use(t.cond,b)
    # 5. phis precede instructions (structural by list separation) - trivially true
    return True
