import test_pipeline as T

class Gen:
    def __init__(self, rng):
        self.rng = rng
        self.fnames = ["f0","f1","f2"]
        self.ftypes = {"f0":"int","f1":"bool","f2":"void"}

    def gen_expr(self, env, typ, depth=0):
        rng=self.rng
        choices=["lit","var"]
        if depth<3: choices += ["arith" if typ=="int" else None, "call",
                                "compare" if typ=="bool" else None,
                                "logical" if typ=="bool" else None]
        choices=[c for c in choices if c]
        c=rng.choice(choices)
        if c=="lit":
            return T.int_(rng.randint(0,5)) if typ=="int" else T.bool_(rng.choice([True,False]))
        if c=="var":
            vs=[n for n,t in env.items() if t==typ]
            if vs: return T.var(rng.choice(vs))
            return T.int_(rng.randint(0,5)) if typ=="int" else T.bool_(True)
        if c=="arith":
            return T.arith(rng.choice(["add","sub","mul"]),
                           self.gen_expr(env,"int",depth+1), self.gen_expr(env,"int",depth+1))
        if c=="compare":
            return T.compare(rng.choice(["eq","lt","gt","le","ge"]),
                             self.gen_expr(env,"int",depth+1), self.gen_expr(env,"int",depth+1))
        if c=="logical":
            return T.logical(rng.choice(["and","or"]),
                             self.gen_expr(env,"bool",depth+1), self.gen_expr(env,"bool",depth+1))
        if c=="call":
            # non-void callees only for value
            name=rng.choice(["f0","f1"])
            args=[self.gen_expr(env,"int",depth+1)] if name=="f0" else [self.gen_expr(env,"bool",depth+1)]
            e=T.call(name,args)
            if self.ftypes[name]!=typ:
                # wrap: just produce a literal to keep types, but call still emitted as stmt elsewhere
                return T.int_(rng.randint(0,5)) if typ=="int" else T.bool_(True)
            return e

    def gen_stmts(self, env, depth, must_return, ret_type):
        rng=self.rng
        stmts=[]
        n=rng.randint(1,4)
        for _ in range(n):
            kind=rng.choice(["let","assign","if","while","callstmt"] + (["return"] if ret_type!="void" else []))
            if kind=="let":
                typ=rng.choice(["int","bool"])
                name=f"v{rng.randint(0,6)}"
                # avoid same-scope duplicate: pick fresh local name
                name=f"l{len(env)}_{rng.randint(0,9999)}"
                stmts.append(T.let(name,typ,self.gen_expr(env,typ)))
                env=dict(env); env[name]=typ
            elif kind=="assign":
                vs=list(env.items())
                if vs:
                    name,typ=rng.choice(vs)
                    stmts.append(T.assign(name,self.gen_expr(env,typ)))
            elif kind=="if" and depth<3:
                then_env=dict(env); else_env=dict(env)
                tb=self.gen_stmts(then_env,depth+1,False,ret_type)
                eb=self.gen_stmts(else_env,depth+1,False,ret_type)
