import sys; sys.path.insert(0,".")
from compiler_ir import lower_module, to_ssa, render_module
from compiler_ir.ir_nodes import Const, Copy, BinOp, Call, Return, Jump, Branch, Slot, Phi, Temp, Block

def edges(b):
    t=b.terminator
    if isinstance(t,Jump): return [t.target]
    if isinstance(t,Branch): return [t.true_target,t.false_target]
    return []

def verify(fn):
    blocks=fn.blocks; entry=fn.entry
    # ---- CFG / reachability ----
    succs={b:edges(b) for b in blocks}
    reach={entry}; st=[entry]
    while st:
        x=st.pop()
        for y in succs[x]:
            if y not in reach: reach.add(y); st.append(y)
    preds={b:[] for b in blocks}
    for x in blocks:
        if x in reach:
            for y in succs[x]:
                if y in reach: preds[y].append(x)

    # ---- dense unique numbering ----
    ids=[p.temp.id for p in fn.params]
    for b in blocks:
        for ph in b.phis: ids.append(ph.dest.id)
        for ins in b.instructions: ids.append(ins.dest.id)
    assert sorted(ids)==list(range(len(ids))), f"ids {sorted(ids)} in {fn.name}"

    # ---- dominator sets to fixpoint (independent of production idom) ----
    allset=set(blocks)
    dom={b:(allset if b is not entry else {entry}) for b in blocks}
    changed=True
    while changed:
        changed=False
        for b in blocks:
            if b is entry or b not in reach: continue
            ps=[p for p in preds[b]]
            nd=set.intersection(*[dom[p] for p in ps])|{b} if ps else {b}
            if nd!=dom[b]: dom[b]=nd; changed=True
    defblock={}
    for p in fn.params: defblock[id(p.temp)]=entry
    for b in blocks:
        for ph in b.phis: defblock[id(ph.dest)]=b
        for ins in b.instructions: defblock[id(ins.dest)]=b

    def no_slot(v):
        assert not isinstance(v,Slot), f"slot {v} in {fn.name}"

    # position of a def within a block (phi => -1)
    def pos_of(v,b):
        for i,ins in enumerate(b.instructions):
            if ins.dest is v: return i
        return -1
    def use_pos(b):
        # map value -> first use instruction index among ordinary ins/term
        positions=[]
        for i,ins in enumerate(b.instructions):
            for v in _ins_ops(ins): positions.append((v,i))
        t=b.terminator
        if isinstance(t,Return) and t.value is not None: positions.append((t.value,len(b.instructions)))
        if isinstance(t,Branch): positions.append((t.cond,len(b.instructions)))
        return positions
    for b in blocks:
        if b not in reach: continue
        # no slots
        for ph in b.phis:
            for v in ph.entries.values(): no_slot(v)
        for ins in b.instructions:
            for v in _ins_ops(ins): no_slot(v)
        t=b.terminator
        if isinstance(t,Return) and t.value is not None: no_slot(t.value)
        if isinstance(t,Branch): no_slot(t.cond)
        # phi entries: exact reachable preds, sorted labels
        for ph in b.phis:
            keys=list(ph.entries.keys())
            assert [k.id for k in keys]==sorted(k.id for k in keys), "unsorted entries"
            assert set(keys)==set(preds[b]), f"phi@ {b.label} preds {[k.label for k in keys]} vs {[p.label for p in preds[b]]}"
            for pred,v in ph.entries.items():
                db=defblock.get(id(v))
                assert db is not None, f"phi uses undef {v}"
                if db is pred:
                    assert pos_of(v,pred)>=0, f"edge value {v} must be an ins def in {pred.label}"
                else:
                    assert pred in dom[db], f"{v}@{db.label} not on edge {pred.label}->{b.label} ({fn.name})"
        # ordinary uses: def dominates block, or same block & earlier
        for v,ui in use_pos(b):
            db=defblock.get(id(v))
            assert db is not None, f"use of undef {v} in {b.label}"
            if db is b:
                dp=pos_of(v,b)
                assert dp>=0 and dp<ui, f"use before def {v} in {b.label}"
            else:
                assert b in dom[db], f"{v}@{db.label} doesn't dominate use@{b.label}"

def _ins_ops(ins):
    if isinstance(ins,Copy): return [ins.src]
    if isinstance(ins,BinOp): return [ins.left,ins.right]
    if isinstance(ins,Call): return list(ins.args)
    return []
