class Gen:
    def __init__(self, rng):
        self.rng=rng; self.ftypes={"f0":"int","f1":"bool","f2":"void"}
    def gen_expr(self, env, typ, depth=0):
        rng=self.rng
        choices=["lit","var","call"]
        if depth<4:
            choices += ["arith"] if typ=="int" else []
            choices += ["compare","logical"] if typ=="bool" else []
        c=rng.choice(choices)
        if c=="lit":
            return T.int_(rng.randint(0,5)) if typ=="int" else T.bool_(rng.choice([True,False]))
        if c=="var":
            vs=[n for n,t in env.items() if t==typ]
            return T.var(rng.choice(vs)) if vs else (T.int_(rng.randint(0,5)) if typ=="int" else T.bool_(True))
        if c=="arith":
            return T.arith(rng.choice(["add","sub","mul"]),self.gen_expr(env,"int",depth+1),self.gen_expr(env,"int",depth+1))
        if c=="compare":
            return T.compare(rng.choice(["eq","lt","gt","le","ge"]),self.gen_expr(env,"int",depth+1),self.gen_expr(env,"int",depth+1))
        if c=="logical":
            return T.logical(rng.choice(["and","or"]),self.gen_expr(env,"bool",depth+1),self.gen_expr(env,"bool",depth+1))
        name=rng.choice(["f0","f1"])
        args=[self.gen_expr(env,"int",depth+1)] if name=="f0" else [self.gen_expr(env,"bool",depth+1)]
        e=T.call(name,args)
        return e if self.ftypes[name]==typ else (T.int_(rng.randint(0,5)) if typ=="int" else T.bool_(True))
    def gen_stmts(self, env, depth, must_return, ret_type):
        rng=self.rng; stmts=[]
        for _ in range(rng.randint(1,4)):
            kinds=["let","assign","if","while","callstmt"]
            if ret_type!="void": kinds.append("return")
            kind=rng.choice(kinds)
            if kind=="let":
                typ=rng.choice(["int","bool"]); name=f"l{len(env)}_{rng.randint(0,10**6)}"
                stmts.append(T.let(name,typ,self.gen_expr(env,typ))); env=dict(env); env[name]=typ
            elif kind=="assign":
                if env:
                    name,typ=rng.choice(list(env.items()))
                    stmts.append(T.assign(name,self.gen_expr(env,typ)))
            elif kind=="if" and depth<4:
                stmts.append(T.if_(self.gen_expr(env,"bool"),
                                   self.gen_stmts(dict(env),depth+1,False,ret_type),
                                   self.gen_stmts(dict(env),depth+1,False,ret_type)))
            elif kind=="while" and depth<4:
                stmts.append(T.while_(self.gen_expr(env,"bool"),
                                      self.gen_stmts(dict(env),depth+1,False,ret_type)))
            elif kind=="return":
                stmts.append(T.ret(self.gen_expr(env,ret_type))); break
            elif kind=="callstmt":
                stmts.append(T.let(f"ig_{rng.randint(0,10**9)}","int",T.call("f0",[self.gen_expr(env,"int")])))
        if must_return and ret_type!="void" and (not stmts or stmts[-1].get("kind")!="return"):
            stmts.append(T.ret(self.gen_expr(env,ret_type)))
        return stmts
    def gen_program(self):
        funcs=[]
        for name in ["f1","f0","f2"]:
            ret=self.ftypes[name]
            pt="int" if name in ("f0","f2") else "bool"
            env={"x":pt}
            funcs.append(T.func(name,[T.param("x",pt)],ret,self.gen_stmts(env,0,ret!="void",ret)))
        return T.program(*funcs)

