        module = lower_module(program(func(
            "f", [param("x", "int")], "void",
            [while_(
                logical("and", compare("gt", var("x"), int_(0)),
                        compare("lt", var("x"), int_(10))),
                [assign("x", arith("sub", var("x"), int_(1)))])],
        )))
        for func in module.functions:
            self.assertTrue(all(
                b.terminator is not None for b in _reachable(func)
            ))
