class PruningTests(unittest.TestCase):
    def test_identical_incoming_value_prunes_phi(self):
        # Both branches assign the same SSA value (`x`) to `a`: the copies
        # fold away, both edges carry the same value, no phi remains.
        module = lower_module(program(func(
            "f", [param("c", "bool"), param("x", "int")], "int",
            [
                let("a", "int", var("x")),
                if_(var("c"),
                    [assign("a", var("x"))],
                    [assign("a", var("x"))]),
                ret(var("a")),
            ],
        )))
        fn = to_ssa(module).functions[0]
        self.assertFalse(any(b.phis for b in fn.blocks))

    def test_unused_result_has_no_phi(self):
        # `a` diverges in the branches but is never read afterwards.
        module = lower_module(program(func(
            "g", [param("c", "bool")], "void",
            [
                let("a", "int", int_(1)),
                if_(var("c"),
                    [assign("a", int_(2))],
                    [assign("a", int_(3))]),
            ],
        )))
        fn = to_ssa(module).functions[0]
        self.assertFalse(any(b.phis for b in fn.blocks))

    def test_phi_only_cycle_for_unread_temporary_is_removed(self):
        # Nested loops where a call temporary gets loop-carried phis that
        # only reference each other and feed no real use: all die.
        module = lower_module(program(
            func("id", [param("x", "int")], "int", [ret(var("x"))]),
            func("f", [param("n", "int")], "int",
                 [
                     let("a", "int", int_(0)),
                     while_(compare("gt", var("n"), int_(0)),
                            [
                                while_(compare("gt", var("a"), int_(10)),
                                       [assign("a",
                                               call("id", [var("a")]))]),
                                assign("n", arith("sub", var("n"), int_(1))),
                            ]),
                     ret(var("a")),
                 ]),
        ))
        fn = next(f for f in to_ssa(module).functions if f.name == "f")
        # The inner header keeps a phi only for the slot `a`; no phi whose
        # result is another phi-only value remains.
        for blk in fn.blocks:
            self.assertLessEqual(len(blk.phis), 1)


